      "en": "And establish them in the land and show Pharaoh and [his minister] Hāmān and their soldiers through them[1094] that which they had feared.",
      "footnotesUr": "[1] یہاں زمین سے مراد ارض شام ہے جہاں وہ کنعانیوں کی زمین کے وارث بنے کیونکہ مصر سے نکلنے کے بعد بنی اسرائیل مصر واپس نہیں گئے، واللهُ أَعْلَمُ۔\n[2] یعنی انہیں جو اندیشہ تھا کہ ایک اسرائیلی کے ہاتھوں فرعون کی اور اس کے ملک ولشکر کی تباہی ہوگی، ان کے اس اندیشے کو ہم نے حقیقت کر دکھایا۔",
