      "en": "And she said to his sister, \"Follow him\"; so she watched him from a distance while they perceived not.",
      "footnotesUr": "[1] خواہر موسیٰ (عليه السلام) کا نام مریم بنت عمران تھا جس طرح حضرت عیسیٰ (عليه السلام) کی والدہ مریم بنت عمران تھیں۔ نام اور ولدیت دونوں میں اتحاد تھا۔\n[2] چنانچہ وہ دریا کے کنارے کنارے ، دیکھتی رہی تھی، حتیٰ کہ اس نے دیکھ لیا کہ اس کا بھائی فرعون کے محل میں چلا گیا ہے۔",
