      "number": 28,
      "arFull": "قَالَ ذٰلِكَ بَیْنِیْ وَبَیْنَكَ ؕ اَیَّمَا الْاَجَلَیْنِ قَضَیْتُ فَلَا عُدْوَانَ عَلَیَّ ؕ وَاللّٰهُ عَلٰی مَا نَقُوْلُ وَكِیْلٌ ۟۠",
      "ur": "موسیٰ (علیہ السلام) نے کہا، خیر تو یہ بات میرے اور آپ کے درمیان پختہ ہوگئی، میں ان دونوں مدتوں میں سے جسے پورا کروں مجھ پر کوئی زیادتی نہ ہو[1] ، ہم یہ جو کچھ کہہ رہے ہیں اس پر اللہ (گواه اور) کارساز ہے.[2]",
      "en": "[Moses] said, \"That is [established] between me and you. Whichever of the two terms I complete - there is no injustice to me, and Allāh, over what we say, is Witness.\"",
      "footnotesUr": "[1] یعنی آٹھ سال کے بعد یا دس سال کے بعد جانا چاہوں تو مجھ سے مزید رہنے کا مطالبہ نہ کیا جائے۔\n[2] یہ بعض کے نزدیک شعیب (عليه السلام) یا برادر زادہ شعیب (عليه السلام) کا قول ہے اور بعض کے نزدیک حضرت موسیٰ (عليه السلام) کا۔ ممکن ہے دونوں ہی کی طرف سے ہو۔ کیونکہ جمع کا صیغہ ہے گویا دونوں نے اس معاملے پر اللہ کو گواہ ٹھہرایا۔ اور اس کے ساتھ ہی ان کی لڑکی اور موسیٰ (عليه السلام) کے درمیان رشتہ ازدواج قائم ہوگیا۔ باقی تفصیلات اللہ نے ذکر نہیں کی ہیں۔ ویسے اسلام میں طرفین کی رضامندی کے ساتھ صحت نکاح کے لیے دو عادل گواہ بھی ضروری ہیں۔",
      "footnotesEn": null,
