      "number": 43,
      "arFull": "وَلَقَدْ اٰتَیْنَا مُوْسَی الْكِتٰبَ مِنْ بَعْدِ مَاۤ اَهْلَكْنَا الْقُرُوْنَ الْاُوْلٰی بَصَآىِٕرَ لِلنَّاسِ وَهُدًی وَّرَحْمَةً لَّعَلَّهُمْ یَتَذَكَّرُوْنَ ۟",
      "ur": "اور ان اگلے زمانہ والوں کو ہلاک کرنے کے بعد ہم نے موسیٰ (علیہ السلام) کو ایسی کتاب عنایت فرمائی[1] جو لوگوں کے لیے دلیل اور ہدایت ورحمت ہوکر آئی تھی[2] تاکہ وه نصیحت حاصل کرلیں.[3]",
      "en": "And We gave Moses the Scripture, after We had destroyed the former generations, as enlightenment for the people and guidance and mercy that they might be reminded.",
      "footnotesUr": "[1] یعنی فرعون اور اس کی قوم یا قوم نوح وعاد وثمود وغیرہ کی ہلاکت کے بعد موسیٰ (عليه السلام) کو کتاب (تورات) دی۔\n[2] جس سے وہ حق کو پہچان لیں اور اسے اختیار کریں اور اللہ کی رحمت کے مستحق قرار پائیں۔\n[3] یعنی اللہ کی نعمتوں کا شکر ادا کریں اور اللہ پر ایمان لائیں اور اس کے پیغمبروں کی اطاعت کریں جو انہیں خیر ورشد اور فلاح حقیقی کی طرف بلاتے ہیں۔",
      "footnotesEn": null,
