      "number": 51,
      "arFull": "وَلَقَدْ وَصَّلْنَا لَهُمُ الْقَوْلَ لَعَلَّهُمْ یَتَذَكَّرُوْنَ ۟ؕ",
      "ur": "اور ہم برابر پے درپے لوگوں کے لیے اپنا کلام بھیجتے رہے[1] تاکہ وه نصیحت حاصل کرلیں.[2]",
      "en": "And We have [repeatedly] conveyed to them the word [i.e., the Qur’ān] that they might be reminded.",
      "footnotesUr": "[1] یعنی ایک رسول کے بعد دوسرا رسول، ایک کتاب کے بعد دوسری کتاب ہم بھیجتے رہے اور اس طرح مسلسل، لگاتار ہم اپنی بات لوگوں تک پہنچاتے رہے۔\n[2] مقصد اس سے یہ تھا کہ لوگ پچھلے لوگوں کے انجام سے ڈر کر اور ہماری باتوں سے نصیحت حاصل کرکے ایمان لے آئیں۔",
