      "arFull": "وَمَاۤ اُوْتِیْتُمْ مِّنْ شَیْءٍ فَمَتَاعُ الْحَیٰوةِ الدُّنْیَا وَزِیْنَتُهَا ۚ وَمَا عِنْدَ اللّٰهِ خَیْرٌ وَّاَبْقٰی ؕ اَفَلَا تَعْقِلُوْنَ ۟۠",
      "ur": "اور تمہیں جو کچھ دیا گیا ہے وه صرف زندگی دنیا کا سامان اور اسی کی رونق ہے، ہاں اللہ کے پاس جو ہے وه بہت ہی بہتر اور دیرپا ہے۔ کیا تم نہیں سمجھتے.[1]",
      "en": "And whatever thing you [people] have been given - it is [only for] the enjoyment of worldly life and its adornment. And what is with Allāh is better and more lasting; so will you not use reason?",
      "footnotesUr": "[1] یعنی کیا اس حقیقت سے بھی تم بےخبر ہو کہ یہ دنیا اور اس کی رونقیں عارضی بھی ہیں اور حقیر بھی، جب کہ اللہ تعالیٰ نے اہل ایمان کے لیے اپنے پاس جو نعمتیں ، آسائشیں اور سہولتیں تیار کر رکھی ہیں، وہ دائمی بھی ہیں اور عظیم بھی۔ حدیث میں ہے ”اللہ کی قسم دنیا، آخرت کے مقابلے میں ایسی ہے جیسے تم میں سے کوئی شخص اپنی انگلی سمندر میں ڈبو کر نکال لے، دیکھے کہ سمندر کے مقابلے میں انگلی میں کتنا پانی ہوگا؟“ (صحيح مسلم، كتاب الجنة، باب فناء الدنيا وبيان الحشر)",
      "footnotesEn": null,
