      "number": 64,
      "arFull": "وَقِیْلَ ادْعُوْا شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ یَسْتَجِیْبُوْا لَهُمْ وَرَاَوُا الْعَذَابَ ۚ لَوْ اَنَّهُمْ كَانُوْا یَهْتَدُوْنَ ۟",
      "ur": "کہا جائے گا کہ اپنے شریکوں کو بلاؤ[1] ، وه بلائیں گے لیکن انہیں وه جواب تک نہ دیں گے اور سب عذاب دیکھ لیں گے[2]، کاش یہ لوگ ہدایت پا لیتے.[3]",
      "en": "And it will be said, \"Invoke your 'partners,'\" and they will invoke them; but they will not respond to them, and they will see the punishment. If only they had followed guidance!",
      "footnotesUr": "[1] یعنی ان سے مدد طلب کرو، جس طرح دنیا میں کرتے تھے۔ کیا وہ تمہاری مدد کرتے ہیں؟ پس وہ پکاریں گے۔ لیکن وہاں کس کو یہ جرات ہوگی کہ جو یہ کہے کہ ہاں ہم تمہاری مدد کرتے ہیں؟\n[2] یعنی یقین کرلیں گے کہ ہم سب جہنم کا ایندھن بننے والے ہیں۔\n[3] یعنی عذاب دیکھ لینے کے بعد آرزو کریں گے کہ کاش دنیا میں ہدایت کا راستہ اپنا لیتے تو آج وہ اس حشر سے بچ جاتے۔ سورۃ الکہف: 53-52 میں بھی یہ مضمون بیان کیا گیا ہے۔",
