      "number": 84,
      "arFull": "مَنْ جَآءَ بِالْحَسَنَةِ فَلَهٗ خَیْرٌ مِّنْهَا ۚ وَمَنْ جَآءَ بِالسَّیِّئَةِ فَلَا یُجْزَی الَّذِیْنَ عَمِلُوا السَّیِّاٰتِ اِلَّا مَا كَانُوْا یَعْمَلُوْنَ ۟",
      "ur": "جو شخص نیکی ﻻئے گا اسے اس سے بہتر ملے گا[1] اور جو برائی لے کر آئے گا تو ایسے بداعمالی کرنے والوں کو ان کے انہی اعمال کا بدلہ دیا جائے گا جو وه کرتے تھے.[2]",
      "en": "Whoever comes [on the Day of Judgement] with a good deed will have better than it; and whoever comes with an evil deed - then those who did evil deeds will not be recompensed except [as much as] what they used to do.",
      "footnotesUr": "[1] یعنی کم ازکم ہر نیکی کا بدلہ دس گنا تو ضرور ہی ملے گا، اور جس کے لیے اللہ چاہے گا، اس سے بھی زیادہ ، کہیں زیادہ، عطا فرمائے گا۔\n[2] یعنی نیکی کا بدلہ تو بڑھا چڑھا کر دیا جائے گا لیکن برائی کا بدلہ برائی کے برابر ہی ملے گا۔ یعنی نیکی کی جزا میں اللہ کے فضل وکرم کا اور بدی کی جزا میں اس کے عدل کا مظاہرہ ہوگا۔",
      "footnotesEn": null,
